er;gap:15px;margin-bottom:22px}.profile-avatar{width:62px;height:62px;border-radius:50%;display:grid;place-items:center;background:#ffe6df;color:#9b503f;font:800 22px Manrope}.profile-card h2{font:800 20px Manrope;margin:0 0 4px}.profile-card p{font-size:12px;color:var(--muted);margin:0}.detail-list{margin:0}.detail-row{padding:14px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:10px;font-size:12px}.detail-row dt{color:var(--muted)}.detail-row dd{margin:0;text-align:right;font-weight:600}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;text-align:left;background:white;font-size:12px;min-width:600px}thead{background:#f4f5fa;color:#5e687b}th,td{padding:13px 14px;border-bottom:1px solid var(--line)}th{font-size:10px;text-transform:uppercase;letter-spacing:.8px}tbody tr:last-child td{border-bottom:0}.empty-state{text-align:center;padding:34px 14px;color:var(--muted);font-size:13px}.empty-state strong{display:block;color:var(--ink);font:700 16px Manrope;margin-bottom:8px}.notice{background:#fff4d8;color:#695523;padding:14px 16px;border-radius:9px;font-size:12px;line-height:1.5;margin-bottom:18px}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);padding:12px 18px;border-radius:9px;background:var(--ink);color:#fff;box-shadow:var(--shadow);font-size:13px;z-index:5}.toast[hidden]{display:none}dialog{width:min(440px,calc(100% - 32px));border:0;border-radius:18px;padding:28px;box-shadow:0 20px 90px #10203c45;color:var(--ink)}dialog::backdrop{background:#17234080;backdrop-filter:blur(3px)}dialog h2{font:800 25px Manrope;margin:17px 0 9px}dialog p{color:var(--muted);font-size:13px;line-height:1.55;margin:0 0 18px}.dialog-top{display:flex;align-items:center;justify-content:space-between}.dialog-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:50%;background:#ddf4e8;color:#267249;font-weight:800;font-size:22px}.icon-button{width:34px;