'use strict';
const courses = [
 {id:'BIO 214',title:'Ecology & the Living World',category:'Science',credits:4,instructor:'Dr. Mara Chen',days:'Mon, Wed',time:'10:00 – 11:15 AM',seats:8,description:'Explore the connections between organisms, ecosystems, and a changing planet.'},
 {id:'ART 108',title:'Color, Form & Expression',category:'Arts',credits:3,instructor:'Prof. Julian Reed',days:'Tue, Thu',time:'1:00 – 2:15 PM',seats:12,description:'Build a visual language through hands-on studies in color and composition.'},
