 {id:'HIS 205',title:'Stories of the Ancient World',category:'Humanities',credits:3,instructor:'Prof. Elias Brooks',days:'Tue, Thu',time:'9:30 – 10:45 AM',seats:16,description:'Read the stories, objects, and ideas that shaped early civilizations.'},
 {id:'MTH 142',title:'Statistics in Everyday Life',category:'Mathematics',credits:4,instructor:'Dr. Owen Kim',days:'Mon, Wed, Fri',time:'11:00 – 11:50 AM',seats:0,description:'Learn how to read data critically and make evidence-based decisions.'},
 {id:'PSY 110',title:'The Psychology of Wellbeing',category:'Social Science',credits:3,instructor:'Dr. Leah Morgan',days:'Tue, Thu',time:'11:00 – 12:15 PM',seats:9,description:'Discover the science behind motivation, relationships, and a meaningful life.'},
 {id:'ENV 320',title:'Climate Futures & Solutions',category:'Science',credits:3,instructor:'Dr. Samira Ali',days:'Wed, Fri',time:'1:00 – 2:15 PM',seats:7,description:'Investigate climate challenges and the creative solutions shaping our future.'},
 {id:'MUS 120',title:'Music Across Cultures',category:'Arts',credits:2,instructor:'Prof. Mateo Rivera',days:'Mon, Wed',time:'3:30 – 4:20 PM',seats:11,description:'Listen across borders and explore music as a living cultural conversation.'},
 {id:'ENG 243',title:'Writing the Short Story',category:'Humanities',credits:3,instructor:'Prof. June Wallace',days:'Tue, Thu',time:'2:30 – 3:45 PM',seats:3,description:'Find your voice through close reading, playful experiments, and revision.'},
 {id:'BUS 201',title:'Ideas into Enterprise',category:'Business',credits:3,instructor:'Prof. Noah Grant',days:'Mon, Wed',time:'9:00 – 10:15 AM',seats:10,description:'Turn an early idea into a thoughtful, customer-focused business plan.'},
 {id:'COM 150',title:'Media, Message & Meaning',category:'Social Science',credits:3,instructor:'Dr. Amara Okafor',days:'Tue, Thu',time:'4:00 – 5:15 PM',seats:6,description:'Explore the way media shapes the stories we share and the world we see.'},
 {id:'DAT 205',title:'Data Visualization Studio',category:'Technology',credits:3,instructor:'Dr. Felix Park',days:'Mon, Wed',time:'12:30 – 1:45 PM',seats:4,description:'Transform complex data into clear, inviting, and trustworthy visuals.'}
];
const student={name:'Jordan Davis',id:'NSU-204891',major:'Environmental Studies',year:'Junior',email:'jordan.davis@northstar.edu',advisor:'Dr. Priya Desai'};
const storageKey='northstar-registered-courses';
function registered(){try{const ids=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(ids)?ids.filter(id=>courses.some(c=>c.id===id)):[]}catch{return []}}
function saveRegistered(ids){localStorage.setItem(storageKey,JSON.stringify([...new Set(ids)]))}
const main=document.querySelector('#main');
const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
function card(c,action='add'){const isAdded=registered().includes(c.id);let button=action==='pick'?"'`<button class="button ${isAdded?'"'button-secondary':'button-primary'}\" type=\"button\" data-course-action=\""'${isAdded?'"'remove':'add'}\" data-course-id=\""'${esc(c.id)}">${isAdded?'"'Remove from schedule':'Add to schedule'}</button>"'`:`<button class="button ${c.seats?'"'button-secondary':'button-secondary'}\" type=\"button\" data-course-action=\""'${c.seats?'"'register':'full'}\" data-course-id=\""'${esc(c.id)}" ${c.seats?'"'':'disabled'}>"'${c.seats?'"'Register for course':'Waitlist full'}</button>"'`;return `<article class="course-card"><div class="course-top"><span class="course-code">${esc(c.id)}</span><span class="course-credits">${c.credits} credits</span></div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="course-meta"><span>${esc(c.category)}</span><span>${esc(c.days)} · ${esc(c.time)}</span><span>${c.seats?`${c.seats} seats left`:'"'Full'}</span></div>"'${button}</article>`}
function courseTiles(ids,action){return ids.map(id=>courses.find(c=>c.id===id)).filter(Boolean).map(c=>card(c,action)).join('"'')}
function heading(label,title,desc){return "'`<div class="page-heading"><p class="eyebrow">${label}</p><h1>${title}</h1><p>${desc}</p></div>`}
function home(){const ids=registered();return `<div class="container"><section class="hero-wrap"><div class="hero"><div class="hero-copy"><p class="eyebrow">Your next chapter starts here</p><h1>Make room for <span style="color:#4969dd">what'"'s next.</span></h1><p>Find the classes that make you curious, challenge your thinking, and move you toward what you want to become.</p><div class=\"hero-actions\"><a class=\"button button-primary\" href=\"#catalog\">Explore courses <span aria-hidden=\"true\">→</span></a><a class=\"button button-secondary\" href=\"#registration\">Plan your semester</a></div></div><div class=\"hero-art\" aria-hidden=\"true\"><div class=\"art-circle\"></div><div class=\"art-shape\"></div><div class=\"art-book\"></div><span class=\"art-spark\">✳</span></div></div></section><section class=\"section\"><div class=\"stat-grid\"><div class=\"stat-card\"><span class=\"stat-icon\" aria-hidden=\"true\">✦</span><div><strong>12</strong><span>courses to explore</span></div></div><div class=\"stat-card\"><span class=\"stat-icon\" aria-hidden=\"true\">◷</span><div><strong>"'${ids.length}</strong><span>courses in your schedule</span></div></div><div class="stat-card"><span class="stat-icon" aria-hidden="true">◎</span><div><strong>${ids.reduce((n,id)=>n+courses.find(c=>c.id===id).credits,0)}</strong><span>credits planned</span></div></div></div><div class="section-head"><h2>Popular this semester</h2><a class="text-link" href="#catalog">Browse all courses <span aria-hidden="true">→</span></a></div><div class="course-grid">${courseTiles(['"'BIO 214','ART 108','CS 231'],'register')}</div></section></div>"'`}
function catalog(){return `<div class="container">${heading('"'Find your next favorite class','Course catalog','A little curiosity can take you a long way. Explore this semester’s courses.') }<form class=\"toolbar\" id=\"catalog-filters\" role=\"search\"><div class=\"search-field\"><label for=\"course-search\"><span aria-hidden=\"true\">⌕</span><span class=\"sr-only\">Search courses</span></label><input id=\"course-search\" type=\"search\" placeholder=\"Search courses, instructors...\" autocomplete=\"off\"></div><div class=\"field filter-field\"><label for=\"category-filter\">Subject area</label><select id=\"category-filter\"><option value=\"\">All subjects</option>"'${[...new Set(courses.map(c=>c.category))].sort().map(v=>`<option>${esc(v)}</option>`).join('"'')}</select></div><div class=\"field filter-field\"><label for=\"availability-filter\">Availability</label><select id=\"availability-filter\"><option value=\"\">Any availability</option><option value=\"open\">Open seats</option><option value=\"full\">Full</option></select></div></form><p class=\"result-count\" id=\"result-count\" aria-live=\"polite\"></p><div class=\"course-grid\" id=\"catalog-grid\">"'${courses.map(c=>card(c,'"'register')).join('')}</div></div>"'`}
function registration(){return `<div class="container">${heading('"'Build a semester that feels like you','Course registration','Choose a course and add it to your schedule in just a few steps.') }<div class=\"notice\"><strong>Registration is open.</strong> Review course details and check your profile for your current schedule at any time.</div><div class=\"registration-layout\"><section class=\"panel\"><h2>Choose a course</h2><p class=\"panel-intro\">Browse available courses or search by title, code, or instructor.</p><div class=\"field\"><label for=\"registration-course\">Course <span aria-hidden=\"true\">*</span></label><select id=\"registration-course\" required><option value=\"\">Select a course</option>"'${courses.map(c=>`<option value="${esc(c.id)}" ${!c.seats?'"'disabled':''}>"'${esc(c.id)} — ${esc(c.title)} (${c.seats?`${c.seats} seats left`:'"'Full'})</option>"'`).join('"'')}</select></div><div id=\"selected-course-detail\" aria-live=\"polite\"></div><form id=\"registration-form\"><input type=\"hidden\" id=\"selected-course-id\"><div class=\"form-grid\"><div class=\"field\"><label for=\"student-name\">Student name <span aria-hidden=\"true\">*</span></label><input id=\"student-name\" name=\"name\" required autocomplete=\"name\" value=\""'${esc(student.name)}"></div><div class="field"><label for="student-id">Student ID <span aria-hidden="true">*</span></label><input id="student-id" name="studentId" required value="${esc(student.id)}"></div><div class="field full"><label for="student-email">University email <span aria-hidden="true">*</span></label><input id="student-email" name="email" type="email" required autocomplete="email" value="${esc(student.email)}"></div></div><p class="required-note">Fields marked <span aria-hidden="true">*</span> are required.</p><div class="form-actions"><button class="button button-primary" type="submit">Confirm registration <span aria-hidden="true">→</span></button><a class="button button-secondary" href="#catalog">Browse courses</a></div></form></section><aside class="helper-card"><span class="pill">A good place to start</span><h2>Your semester, your way.</h2><p>Choose a course that fits your interests and the time you have. You can see your full schedule on your profile.</p><ul><li>Course codes make finding classes easy</li><li>Check seats and meeting times</li><li>Your schedule saves on this device</li></ul></aside></div></div>`}
function profile(){const ids=registered();const credits=ids.reduce((n,id)=>n+courses.find(c=>c.id===id).credits,0);return `<div class="container">${heading('"'A little home base','My profile','Your details and the courses you have planned for this semester.') }<div class=\"profile-layout\"><section class=\"panel\"><div class=\"profile-card\"><div class=\"profile-avatar\" aria-hidden=\"true\">JD</div><div><h2>"'${esc(student.name)}</h2><p>${esc(student.major)} · ${esc(student.year)}</p></div></div><dl class="detail-list"><div class="detail-row"><dt>Student ID</dt><dd>${esc(student.id)}</dd></div><div class="detail-row"><dt>University email</dt><dd>${esc(student.email)}</dd></div><div class="detail-row"><dt>Academic advisor</dt><dd>${esc(student.advisor)}</dd></div><div class="detail-row"><dt>Current credits</dt><dd>${credits} credits</dd></div></dl><p style="margin:19px 0 0"><a href="#registration" class="button button-primary">Add a course <span aria-hidden="true">→</span></a></p></section><section class="panel"><div class="section-head" style="margin-bottom:15px"><div><p class="eyebrow">Fall 2026</p><h2>My schedule</h2></div><span class="pill">${ids.length} ${ids.length===1?'"'course':'courses'}</span></div>"'${ids.length?`<div class="table-wrap"><table><caption class="sr-only">Registered courses for Fall 2026</caption><thead><tr><th scope="col">Course</th><th scope="col">Meeting time</th><th scope="col">Credits</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${ids.map(id=>{const c=courses.find(x=>x.id===id);return `<tr><td><strong>${esc(c.id)}</strong><br>${esc(c.title)}</td><td>${esc(c.days)}<br>${esc(c.time)}</td><td>${c.credits}</td><td><button class="text-link" type="button" data-course-action="remove" data-course-id="${esc(c.id)}" aria-label="Remove ${esc(c.id)} ${esc(c.title)} from schedule">Remove</button></td></tr>`}).join('"'')}</tbody></table></div>"'`:`<div class="empty-state"><strong>Your schedule is a blank page.</strong>Add a course to start building your semester.<br><a class="text-link" href="#catalog">Explore the catalog →</a></div>`}</section></div></div>`}
function route(){const page=location.hash.slice(1)||'"'home';const valid=['home','catalog','registration','profile'].includes(page)?page:'home';document.querySelectorAll('[data-route]').forEach(a=>{if(a.dataset.route===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});main.innerHTML=({home,catalog,registration,profile}[valid])();document.querySelector('#primary-nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');if(valid==='catalog')updateCatalog();if(valid==='registration')refreshRegistration();}
function updateCatalog(){const grid=document.querySelector('#catalog-grid');if("'!grid)return;const q=(document.querySelector('"'#course-search').value||'').trim().toLowerCase(),cat=document.querySelector('#category-filter').value,avail=document.querySelector('#availability-filter').value;const found=courses.filter(c=>("'!q||[c.id,c.title,c.instructor,c.category].some(v=>v.toLowerCase().includes(q)))&&(!cat||c.category===cat)&&(!avail||(avail==='"'open'?c.seats>0:c.seats===0)));document.querySelector('#result-count').textContent="'`${found.length} ${found.length===1?'"'course':'courses'} found"'`;grid.innerHTML=found.length?found.map(c=>card(c,'"'register')).join(''):'<div class=\"empty-state catalog-empty\"><strong>No courses found.</strong>Try a different search or clear a filter.</div>'}
function refreshRegistration(){const select=document.querySelector('#registration-course');if("'!select)return;const ids=registered();[...select.options].forEach(o=>{if(o.value)o.disabled=!courses.find(c=>c.id===o.value).seats||ids.includes(o.value)});const sel=select.value;const c=courses.find(x=>x.id===sel);document.querySelector('"'#selected-course-id').value=c&&"'!ids.includes(sel)&&c.seats?sel:'"'';document.querySelector('#selected-course-detail').innerHTML=c?"'`<div class="notice" style="margin:15px 0">${esc(c.description)}<br><strong>${esc(c.instructor)}</strong> · ${esc(c.days)}, ${esc(c.time)} · ${c.credits} credits${ids.includes(sel)?'"' · Already in your schedule':''}</div>"'`:'"''}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,3000)}
function registerCourse(id){const c=courses.find(x=>x.id===id);if("'!c||!c.seats){notify('"'This course is full.');return}if(registered().includes(id)){notify('This course is already in your schedule.');return}saveRegistered([...registered(),id]);document.querySelector('#dialog-course').innerHTML="'`<strong>${esc(c.id)} · ${esc(c.title)}</strong>${c.credits} credits · ${esc(c.days)}, ${esc(c.time)}`;document.querySelector('"'#confirm-dialog').showModal();route()}
document.addEventListener('click',e=>{const action=e.target.closest('[data-course-action]');if(action){const id=action.dataset.courseId;if(action.dataset.courseAction==='register')registerCourse(id);else if(action.dataset.courseAction==='add'){if("'!registered().includes(id)){saveRegistered([...registered(),id]);notify(`${id} added to your schedule.`);route()}}else if(action.dataset.courseAction==='"'remove'){saveRegistered(registered().filter(x=>x"'!==id));notify(`${id} removed from your schedule.`);route()}else if(action.dataset.courseAction==='"'full')notify('This course is full.');return}if(e.target.closest('[data-close-dialog]'))document.querySelector('#confirm-dialog').close()});
document.addEventListener('input',e=>{if(e.target.matches('#course-search'))updateCatalog()});document.addEventListener('change',e=>{if(e.target.matches('#category-filter,#availability-filter'))updateCatalog();if(e.target.matches('#registration-course'))refreshRegistration()});
